void comprobar_dos(std::mt19937& motor, const std::vector<int>& candidatos) {
    const std::vector<int> original = candidatos;
    std::mt19937 testigo = motor;
    const int total = static_cast<int>(candidatos.size());
    std::uniform_int_distribution<int> primera_posicion{0, total - 1};
    const int primera = primera_posicion(testigo);
    const int primer_id = candidatos.at(primera);
    std::uniform_int_distribution<int> segunda_posicion{0, total - 2};
    const int segunda = segunda_posicion(testigo);
    int segundo_id = candidatos.at(segunda);
    if (segunda == primera) {
        segundo_id = candidatos.at(total - 1);
    }
    const std::vector<int> esperados{primer_id, segundo_id};
    const std::vector<int> obtenidos = seleccionar(motor, candidatos, 2);
    std::cout << "Orden:" << (obtenidos == esperados)
              << ";Motor:" << (motor == testigo)
              << ";Original:" << (candidatos == original) << '\n';
}

